<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserTemporalPasswordAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserTemporalPasswordAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserTemporalPasswordAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isTemporalPassword returns null on a freshly created holder.
     */
    public function testTemporalPasswordNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserTemporalPasswordAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTemporalPasswordAssigned());
        $this->assertNull($holder->isTemporalPassword());
    }
}
class ImplWithUserTemporalPasswordAttributeHolderUnitTest
{
    use UserTemporalPasswordAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTemporalPasswordRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTemporalPassword();
    }
}
